create schema private_website_content;
revoke all on schema private_website_content from public,anon;
grant usage on schema private_website_content to authenticated;
create table private_website_content.documents(key text primary key,kind text not null check(kind in ('project','home','about','brand')),label text not null,version bigint not null default 1,draft jsonb not null,published jsonb,published_at timestamptz,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table private_website_content.revisions(id uuid primary key default gen_random_uuid(),document_key text not null references private_website_content.documents(key),actor_id uuid not null references auth.users(id),version bigint not null,action text not null check(action in ('save','publish','restore')),snapshot jsonb not null,note text not null default '',created_at timestamptz not null default now());
create index content_revisions_document on private_website_content.revisions(document_key,version desc);
alter table private_website_content.documents enable row level security;
alter table private_website_content.revisions enable row level security;
revoke all on private_website_content.documents,private_website_content.revisions from public,anon,authenticated;
create function private_website_content.validate(k text,d jsonb) returns void language plpgsql set search_path='' as $$
declare kind text;allowed text[];v record;items jsonb;item jsonb;
begin
 kind:=case when k like 'project:%' then 'project' when k='page:home' then 'home' when k='page:about' then 'about' when k='brand:defaults' then 'brand' else null end;
 if kind is null or jsonb_typeof(d)<>'object' or length(d::text)>48000 then raise exception 'Invalid content document';end if;
 allowed:=case kind
 when 'project' then array['title','category','description','problem','outcome','milestones','skills','commitment','repository','collaboration','roles']
 when 'home' then array['headline','intro','primary_label','primary_href','secondary_label','secondary_href','faqs','ecosystem']
 when 'about' then array['headline','intro','support','story','mission','founder_name','founder_role','founder_quote','founder_image','founder_image_alt','hero_image','hero_image_alt','founder_linkedin','founder_website']
 else array['organisation_name','organisation_description','tagline','share_image','share_image_alt','linkedin','instagram','website'] end;
 allowed:=allowed||array['seo_title','seo_description','share_title','share_description','share_image','share_image_alt'];
 for v in select key,value from jsonb_each(d) loop
  if not v.key=any(allowed) then raise exception 'Unsupported content field: %',v.key;end if;
  if v.key in ('roles','faqs','ecosystem') then
   if jsonb_typeof(v.value)<>'array' or jsonb_array_length(v.value)>20 then raise exception 'Invalid content entries';end if;
  else
   if jsonb_typeof(v.value)<>'string' or length(v.value#>>'{}')>(case when v.key='description' then 5000 when v.key='story' then 3000 when v.key in ('problem','outcome','milestones','collaboration','founder_quote') then 2000 when v.key in ('title','seo_title','share_title','tagline') then 180 when v.key in ('seo_description','share_image_alt','hero_image_alt','founder_image_alt','commitment') then 320 else 1200 end) then raise exception 'Check content field: %',v.key;end if;
   if v.key in ('repository','share_image','hero_image','founder_image','founder_linkedin','founder_website','linkedin','instagram','website','primary_href','secondary_href') and v.value#>>'{}'<>'' then
    if (v.value#>>'{}') ~ '[[:space:]<>\\]' or ((v.value#>>'{}') !~ '^https://[^/@[:space:]]+(/[^[:space:]]*)?$' and (v.value#>>'{}') !~ '^/($|[^/])') then raise exception 'Use HTTPS links or website image paths';end if;
    if v.key in ('primary_href','secondary_href') and (v.value#>>'{}') !~ '^/($|[^/])' then raise exception 'Choose a destination on this website';end if;
   end if;
  end if;
 end loop;
 if kind='project' and (length(btrim(coalesce(d->>'title','')))<5 or length(btrim(coalesce(d->>'description','')))<20 or length(btrim(coalesce(d->>'problem','')))<10 or coalesce(d->>'repository','') !~ '^https://[^/@[:space:]]+/[^[:space:]]+') then raise exception 'Complete the project title, summary, problem and HTTPS repository';end if;
 if kind='home' then
  if jsonb_typeof(d->'faqs') is distinct from 'array' or jsonb_typeof(d->'ecosystem') is distinct from 'array' or jsonb_array_length(d->'ecosystem')<>7 then raise exception 'Keep the seven ecosystem sections and check the FAQ entries';end if;
  for item in select value from jsonb_array_elements(d->'faqs') loop
   if jsonb_typeof(item)<>'object' or length(btrim(coalesce(item->>'question','')))=0 or length(btrim(coalesce(item->>'answer','')))=0 or length(item->>'question')>200 or length(item->>'answer')>2000 or exists(select 1 from jsonb_object_keys(item)x where x not in ('question','answer')) then raise exception 'Complete each FAQ question and answer';end if;
  end loop;
  for item in select value from jsonb_array_elements(d->'ecosystem') loop
   if jsonb_typeof(item)<>'object' or length(btrim(coalesce(item->>'title','')))=0 or length(btrim(coalesce(item->>'description','')))=0 or length(item->>'title')>180 or length(item->>'description')>2000 or exists(select 1 from jsonb_object_keys(item)x where x not in ('title','description')) then raise exception 'Complete each ecosystem section';end if;
  end loop;
 end if;
end $$;
create function private_website_content.admin(a text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid();k text:=p->>'key';doc private_website_content.documents;rev private_website_content.revisions;data jsonb;expected bigint;pg integer:=greatest(1,least(100000,coalesce((p->>'page')::integer,1)));q text:=left(coalesce(p->>'q',''),150);total integer;note text:=left(btrim(coalesce(p->>'note','')),500);
begin
 if not private_website_lab.permitted(actor,case when a='list_projects' or (a in ('get','save','publish','restore') and k like 'project:%') then 'operations' else 'roles' end) then raise exception 'Authorised website administrator required' using errcode='42501';end if;
 if a='list_projects' then
  select count(*) into total from public.website_project_briefs b where q='' or concat_ws(' ',b.project_ref,b.title) ilike '%'||q||'%';
  return jsonb_build_object('page',pg,'page_size',25,'total',total,'rows',coalesce((select jsonb_agg(to_jsonb(x)) from(select b.project_ref,coalesce(d.published->>'title',b.title) title,d.version,d.published_at,d.updated_at,d.draft is distinct from d.published has_draft from public.website_project_briefs b left join private_website_content.documents d on d.key='project:'||b.project_ref where q='' or concat_ws(' ',b.project_ref,b.title,d.draft->>'title') ilike '%'||q||'%' order by b.project_ref limit 25 offset (pg-1)*25)x),'[]'));
 elsif a='list_pages' then return coalesce((select jsonb_agg(jsonb_build_object('key',key,'label',label,'version',version,'published_at',published_at,'has_draft',draft is distinct from published) order by key) from private_website_content.documents where kind<>'project'),'[]');end if;
 if k is null or k !~ '^(project:MTL-[A-Z0-9-]+|page:(home|about)|brand:defaults)$' then raise exception 'Content not found';end if;
 perform pg_advisory_xact_lock(hashtextextended('website-content:'||k,0));
 if k like 'project:%' and not exists(select 1 from private_website_content.documents where key=k) then
  insert into private_website_content.documents(key,kind,label,draft,published,published_at)
  select k,'project',b.title,j.data,j.data,now() from public.website_project_briefs b join private_website_lab.market_proposals mp on mp.project_ref=b.project_ref and mp.state='approved' cross join lateral(select jsonb_build_object('title',b.title,'category',mp.category,'description',mp.description,'problem',mp.problem,'outcome',mp.outcome,'milestones',mp.milestones,'skills',array_to_string(array(select jsonb_array_elements_text(mp.skills)),', '),'commitment',mp.commitment,'repository',mp.supporting_url,'collaboration',mp.collaboration,'roles',b.roles,'seo_title',b.title||' | Mettelo','seo_description',left(mp.description,300),'share_title',b.title,'share_description',left(mp.description,500),'share_image','','share_image_alt','') data)j where b.project_ref=substring(k from 9) on conflict do nothing;
 end if;
 select * into doc from private_website_content.documents where key=k for update;
 if not found then raise exception 'Content not found';end if;
 if a='get' then return to_jsonb(doc)||jsonb_build_object('revisions',coalesce((select jsonb_agg(to_jsonb(x)) from(select rr.id,rr.version,rr.action,rr.note,rr.created_at,rr.snapshot from private_website_content.revisions rr where rr.document_key=k order by rr.version desc limit 30)x),'[]'));end if;
 expected:=(p->>'expected_version')::bigint;
 if expected is null or expected<>doc.version then raise exception 'This content changed. Reload before saving to avoid overwriting another administrator.' using errcode='40001';end if;
 if a='save' then data:=p->'data';
 elsif a='restore' then select * into rev from private_website_content.revisions where id=(p->>'revision_id')::uuid and document_key=k;if not found then raise exception 'Revision not found';end if;data:=rev.snapshot;
 elsif a='publish' then
  if p->>'confirmed' is distinct from 'true' or length(note)<8 then raise exception 'Review the preview and describe the change before publishing';end if;
  data:=doc.draft;
 else raise exception 'Unsupported content action';end if;
 perform private_website_content.validate(k,data);
 if doc.kind='project' and data->'roles' is distinct from doc.published->'roles' then raise exception 'Manage placement roles in Project teams; brief editing cannot change member responsibilities';end if;
 if not exists(select 1 from private_website_content.revisions where document_key=k) then insert into private_website_content.revisions(document_key,actor_id,version,action,snapshot,note) values(k,actor,doc.version,'save',doc.draft,'Starting version before editing');end if;
 insert into private_website_content.revisions(document_key,actor_id,version,action,snapshot,note) values(k,actor,doc.version+1,a,data,note);
 update private_website_content.documents set draft=data,published=case when a='publish' then data else published end,published_at=case when a='publish' then now() else published_at end,version=version+1,updated_by=actor,updated_at=now() where key=k;
 if a='publish' and doc.kind='project' then update public.website_project_briefs set title=data->>'title' where project_ref=substring(k from 9);end if;
 return jsonb_build_object('ok',true,'key',k,'version',doc.version+1);
end $$;
revoke all on function private_website_content.admin(text,jsonb),private_website_content.validate(text,jsonb) from public,anon,authenticated;
grant execute on function private_website_content.admin(text,jsonb) to authenticated;
create function public.website_content_admin(p_action text,p_payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private_website_content.admin(p_action,p_payload)$$;
revoke all on function public.website_content_admin(text,jsonb) from public,anon;
grant execute on function public.website_content_admin(text,jsonb) to authenticated;
create function public.website_content_public(p_key text) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('key',key,'data',published,'published_at',published_at) order by key),'[]') from private_website_content.documents where published is not null and (key=p_key or (p_key='projects' and kind='project'))$$;
revoke all on function public.website_content_public(text) from public;
grant execute on function public.website_content_public(text) to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('website-content-assets','website-content-assets',true,5242880,array['image/webp']) on conflict(id) do nothing;
create policy website_content_asset_insert on storage.objects for insert to authenticated with check(bucket_id='website-content-assets' and private_website_lab.permitted((select auth.uid()),'roles') and (storage.foldername(name))[1]=(select auth.uid())::text);

