mage_alt":""}},{"key":"project:MTL-DS-008","kind":"project","label":"NHS Waiting List Demand Forecasting & Capacity Planning","data":{"title":"NHS Waiting List Demand Forecasting & Capacity Planning","category":"Data Science","description":"An NHS planning team needs to understand how waiting-list pressure could develop so it can examine future capacity needs. Build and backtest a waiting-list forecast, explain its uncertainty and translate the results into planning scenarios.","problem":"Forecast future RTT waiting-list pressure and translate the forecast into practical capacity-planning insight.","outcome":"","milestones":"","skills":"Data Science, Machine Learning, Forecasting, Python, Time Series, Model Evaluation, Backtesting, Healthcare Analytics","commitment":"","repository":"https://github.com/Mettelo/MTL-DS-008-NHS-Waiting-List-Demand-Forecasting-Capacity-Planning","collaboration":"","roles":["Data Scientist","Data Analyst"],"seo_title":"NHS Waiting List Demand Forecasting & Capacity Planning | Mettelo","seo_description":"An NHS planning team needs to understand how waiting-list pressure could develop so it can examine future capacity needs. Build and backtest a waiting-list forecast, explain its uncertainty and translate the results into planning scenarios.","share_title":"NHS Waiting List Demand Forecasting & Capacity Planning","share_description":"An NHS planning team needs to understand how waiting-list pressure could develop so it can examine future capacity needs. Build and backtest a waiting-list forecast, explain its uncertainty and translate the results into planning scenarios.","share_image":"","share_image_alt":""}},{"key":"project:MTL-DS-009","kind":"project","label":"London Fire Incident Response Demand & Risk Modelling","data":{"title":"London Fire Incident Response Demand & Risk Modelling","category":"Data Science","description":"A fire-service planning team needs to understand which recorded incident characteristics are associated with higher response demand. Build an explainable classification model and assess its reliability so planners can investigate demand patterns responsibly.","problem":"Develop an explainable classification model that identifies incidents associated with higher operational response demand while controlling leakage and model risk.","outcome":"","milestones":"","skills":"Data Science, Machine Learning, Classification, Python, Feature Engineering, XGBoost, SHAP, Model Validation, Explainability","commitment":"","repository":"https://github.com/Mettelo/MTL-DS-009-London-Fire-Incident-Response-Demand-Risk-Modelling","collaboration":"","roles":["Data Scientist","ML Engineer","Model Governance / Assurance"],"seo_title":"London Fire Incident Response Demand & Risk Modelling | Mettelo","seo_description":"A fire-service planning team needs to understand which recorded incident characteristics are associated with higher response demand. Build an explainable classification model and assess its reliability so planners can investigate demand patterns responsibly.","share_title":"London Fire Incident Response Demand & Risk Modelling","share_description":"A fire-service planning team needs to understand which recorded incident characteristics are associated with higher response demand. Build an explainable classification model and assess its reliability so planners can investigate demand patterns responsibly.","share_image":"","share_image_alt":""}},{"key":"project:MTL-AI-010","kind":"project","label":"NHS Operational Guidance Knowledge Assistant","data":{"title":"NHS Operational Guidance Knowledge Assistant","category":"Artificial Intelligence","description":"NHS staff need a clearer way to find answers in approved operational and statistical guidance. Build a knowledge assistant that retrieves relevant evidence, cites its sources and declines to answer when the guidance does not support a reliable response.","problem":"Build a RAG assistant that answers NHS operational and statistical guidan